"""Utilities for migrating Meridian CRM legacy storage conventions."""

from decimal import Decimal, ROUND_HALF_UP

__all__ = ["to_iso", "from_iso", "yn", "to_minor_units"]


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date value to ISO YYYY-MM-DD."""
    if yyyymmdd in (None, "", "00000000"):
        return None
    return f"{yyyymmdd[:4]}-{yyyymmdd[4:6]}-{yyyymmdd[6:]}"


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date value to the legacy YYYYMMDD format."""
    if iso in (None, ""):
        return "00000000"
    return iso.replace("-", "")


def yn(char: str | None) -> bool:
    """Convert the legacy Y/N flag convention to a boolean."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy decimal amount to integer currency minor units."""
    if amount is None or (isinstance(amount, str) and not amount.strip()):
        return 0

    currency_code = (currency or "").strip().upper()
    exponent = 0 if currency_code == "JPY" else 2

    value = Decimal(str(amount)).scaleb(exponent)
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
